Method.Implementation:
$$$TRACE("Inside "_..%ConfigName_" Method ProcessShspMaSupClaimGetExtract " _ $ZDATETIME($HOROLOG,1,1,9)) #dim tSC As %Status=$$$OK
set clmType = "P" set numBatches = pRequest.profBatchCounts
if (numBatches = 0) { $$$LOGWARNING("Batch count is zero, not calling the stored procedure. Prof count: " _ pRequest.profBatchCounts) return $$$OK }
// KILL ^ClaimsColumnsMaSup
set tSC=..Adapter.SetAutoCommit(1)
set p = 6 set tQuery="{ call TPDS.PK_MASUP_NONDEN_CLMS_MGR.SHSP_MA_SUP_NONDEN_CLM_GET_EXT (?,?,?,?,?,?,?,?)}" set p(1)=pRequest.pFileGuid
set p(3)="" set p(4)="" set p(5)=""
//Control number SET p(3,"IOType")=$$$SQLPARAMOUTPUT set p(3,"SqlType")=$$$SqlNumeric
//Plan type SET p(4,"IOType")=$$$SQLPARAMOUTPUT set p(4,"SqlType")=$$$SqlVarchar
//P_PROV SET p(5,"IOType")=$$$SQLPARAMOUTPUT set p(5,"SqlType")=$$$SqlWLongVarchar set p(5,"LOB")=0
//P_SUBC SET p(6,"IOType")=$$$SQLPARAMOUTPUT set p(6,"SqlType")=$$$SqlWLongVarchar set p(6,"LOB")=0
//P_MA_SUPP_BENEFITS SET p(7,"IOType")=$$$SQLPARAMOUTPUT set p(7,"SqlType")=$$$SqlWLongVarchar set p(7,"LOB")=0
//P_CLAIM SET p(8,"IOType")=$$$SQLPARAMOUTPUT set p(8,"SqlType")=$$$SqlWLongVarchar set p(8,"LOB")=0 FOR batchNum=1:1:numBatches { set p(2)= batchNum
set glbNm = "^ClaimsData." _clmType _ ".BatchNum" _ batchNum if ($DATA(@glbNm) '= 0) { WRITE !, glbNm _ "- Exists: " _ $DATA(@glbNm) KILL @glbNm }
set @glbNm@("pBatchNumber") = batchNum _ " of " _ numBatches set @glbNm@("pFileGuid") = pRequest.pFileGuid
$$$TRACE("ShspMaSupNonDenClaimGetExtract RequestParams: "_p(1)_", "_p(2) _ " @ " _$ZDATETIME($HOROLOG,1,1,9)) SET pResultSnapshots = ##class(%ListOfObjects).%New() FOR index=1:1:4 { SET snap = ##class(EnsLib.SQL.Snapshot).%New() SET snap.MaxRowsToGet = -1 // -1 all rows. default 250 DO pResultSnapshots.Insert(snap) } try{ $$$TRACE("******* Before SP(ShspMaSupClaimGetExtract) call*************") set tSC=..Adapter.ExecuteProcedureParmArray(.pResultSnapshots,.pOutParam,tQuery,"iioooooo*",.p) $$$TRACE("******* After SP(ShspMaSupClaimGetExtract) call*************") $$$TRACE(" pOutParam : "_pOutParam) $$$TRACE(" TEST : ") $$$TRACE(" SUCCESS : "_tSC) }CATCH err { $$$LOGERROR( "Error while calling stored procedure " _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code) set tSC = $$$ERROR( "SQLError:Error while calling stored procedure " _ err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
}
$$$TRACE("ShspMaSupClaimGetExtract Total snapshots count: "_pResultSnapshots.Count()) $$$TRACE( "ShspMaSupClaimGetExtract Providers count: "_pResultSnapshots.GetAt(2).RowCount) $$$TRACE( "ShspMaSupClaimGetExtract Subs count: "_pResultSnapshots.GetAt(3).RowCount)
set @glbNm@("ProvCount") = pResultSnapshots.GetAt(2).RowCount set @glbNm@("SubsCount") = pResultSnapshots.GetAt(3).RowCount set @glbNm@("ClaimCount") = pResultSnapshots.GetAt(4).RowCount set @glbNm@("pControlNum") = pOutParam.GetAt(1) set @glbNm@("pPlanType") = pOutParam.GetAt(2) set @glbNm@("ExecutionTime") = $ZDATETIME($HOROLOG,1,1,9)
Do ..CopyData(pResultSnapshots, clmType, batchNum, pResultSnapshots.GetAt(1).RowCount)
set pResSnapShots = ##class("IHC.ITF.Response.ShRefCursorsMaSupNonDental").%New() set pResSnapShots.ListOfSnaps = pResultSnapshots
set pResSnapShots.ParametersOut=pOutParam $$$TRACE("Resp Count "_pResSnapShots.ParametersOut.Count() _ " @ " _ $ZDATETIME($HOROLOG,1,1,9)) set pResSnapShots.pControlNum = pResSnapShots.ParametersOut.GetAt(1) set pResSnapShots.pPlanType = pResSnapShots.ParametersOut.GetAt(2) $$$TRACE(" pControlNum:: "_pResSnapShots.pControlNum) $$$TRACE(" pPlanType:: "_pResSnapShots.pPlanType _", " _ pRequest.profGuid)
} $$$TRACE("Exit "_..%ConfigName_" Method ShspMaSupClaimGetExtract... " _ $ZDATETIME($HOROLOG,1,1,9)) Quit $$$OK

#dim snapShot As EnsLib.SQL.Snapshot
set parentId = "", key ="",value = "", preFix1 = "", preFix2 = "", rowId = "", rowId2 = ""


set glbNm = "^ClaimsData." _clmType _ ".BatchNum" _ batchNum
set parentIdArr = -1
set parentPROVID = -1
set parentCLMDTLID = -1
set parentCLM = -1
set provNum = 1
set subNum = 1
set clmNum = 1
set diagNum = 1
set lookUpNum = 1
set hospNum = 1

set delim = ","


FOR snpCnt=2:1:4
{
	set snapShot = pResultSnapshots.GetAt(snpCnt)
	set colCnt = snapShot.GetColumnCount()
	$$$TRACE("snpCnt: " _ snpCnt _ "ColCnt: " _ colCnt)
	$$$TRACE($DATA(^ClaimsColumnsMaSupNonDental(snpCnt)))
	if ($DATA(^ClaimsColumnsMaSupNonDental(snpCnt)) = 0)
	{
		$$$TRACE("Creating columns")
		set createClaimsColumns = 1
	}
	else
	{
		$$$TRACE("Not creating columns")
		set createClaimsColumns = 0
	}
	$$$TRACE("Creating columns")
		set createClaimsColumns = 1
	while snapShot.Next()
	{
		$$$TRACE("IN WHILE")
		for colIn=1:1:colCnt
		{
			$$$TRACE("STARTING COLUMN")
			set colNm = $ZSTRIP(snapShot.GetColumnName(colIn),"<>WC")	
			set data = $ZSTRIP(snapShot.GetData(colIn),"<>WC")	
			$$$TRACE(snpCnt_ "-" _ colNm)
			// Store the Column names from the resultset
			if (colIn = 1)
			{
				if (createClaimsColumns = 1)
				{
					set ^ClaimsColumnsMaSupNonDental(snpCnt) = $REPLACE(colNm, "_", "") // Remove "_"
				}
				set value = data
			}
			else
			{
				if (createClaimsColumns = 1)
				{
					set ^ClaimsColumnsMaSupNonDental(snpCnt) = ^ClaimsColumnsMaSupNonDental(snpCnt) _"#~#" _ $REPLACE(colNm, "_" , "")
				}
				set value = value _"#~#" _ data
			}
			if (colIn=colCnt)
			{
				// Last field, save the record


				// $$$TRACE("Save:- snapShot: " _ snpCnt _", Parent: " _ parentId _ ", row Ids: "_ rowId _", " _ rowId2)

				if (parentId = "")
				{	
				   set @glbNm@(key) = value
				}
				else
				{
					set parentIdArr(preFix1_rowId) = parentId _ delim_ preFix1_rowId

					SET count=$LENGTH(parentId,delim)
					if (count >= 2)
					{
						set key1 =$PIECE(parentId,delim,1)
						if (count = 2)
						{
							set key2 =$PIECE(parentId,delim,2)
							set @glbNm@(key1 , key2 , preFix1_rowId) = value
						}
						elseif (count = 3)
						{
							set key2 =$PIECE(parentId,delim,2)
							set key3 =$PIECE(parentId,delim,3)
							set @glbNm@(key1 , key2 , key3 , preFix1_rowId) = value
						}
						elseif (count = 4)
						{
							set key2 =$PIECE(parentId,delim,2)
							set key3 =$PIECE(parentId,delim,3)
							set key4 =$PIECE(parentId,delim,4)
							set @glbNm@(key1 , key2 , key3 , key4 , preFix1_rowId) = value
						}
						elseif (count = 5)
						{
							set key2 =$PIECE(parentId,delim,2)
							set key3 =$PIECE(parentId,delim,3)
							set key4 =$PIECE(parentId,delim,4)
							set key5 =$PIECE(parentId,delim,5)
							set @glbNm@(key1 , key2 , key3 , key4 , key5 , preFix1_rowId) = value
						}
					}
					else
					{
						set @glbNm@(parentId , preFix1_rowId) = value
					}


					if (rowId2 '= "") // CLCLID
					{
						set parentIdArr(preFix2_rowId2) = parentId _ delim_ preFix2_rowId2
						// $$$TRACE("parentIdArr: " _ preFix2_rowId2 _" = " _ parentId _ delim_ preFix2_rowId2)
						set rowId2 = ""													
					}
				}

				set parentId = ""
			}
			else
			{
				if ((snpCnt=2) && (colNm = "CLM_PROV_ID")) // BILLPROV - ROW_BILL_PROV
				{					
					set key = claimsCount + provNum _"-" _ data
					set parentPROVID(data) = key
					Do $INCREMENT(provNum)
				}
				elseif (snpCnt=3)  // SUBSC - ROW_SUBSC
				{
					set preFix1 = "SUBSC-"
					if (colNm = "PARENT_CLM_PROV_ID")
					{
						set parentId = parentPROVID(data)
					}
					elseif (colNm = "CLM_MBR_ID_AND_CLM_SET")
					{
						set rowId = claimsCount + subNum _"-" _ data
						set parentSUBSC(data) = rowId
						Do $INCREMENT(subNum)
					}				
				}
				elseif (snpCnt=4) // CLAIM - ROW_CLAIM
				{
					set preFix1 = "CLAIM-"
					set preFix2 = "CLCLID-"
					if (colNm = "PARENT_CLM_MBR_ID_AND_CLM_SET")
					{

						set subcId = parentSUBSC(data)						
						set parentId = parentIdArr("SUBSC-"_subcId)
					}
					elseif ( colNm = "CLM_PK_ID")
					{				
						set rowId = claimsCount + clmNum _"-" _ data
						set parentCLM(data) = rowId
						Do $INCREMENT(clmNum)
					}
					elseif ( colNm = "CLAIMID")
					{
						set rowId2 = data					
					}

				}

			}

		}

	}



}

return $$$OK
